return items.map((item, index) => {
  let parsed = {};

  // Parse AI output if present
  if (item.json.output) {
    try {
      parsed = JSON.parse(item.json.output);
    } catch (e) {}
  }

  // Get ORIGINAL supplier data from Split Out node
  const original = $items("Split Suppliers")[index].json;

  return {
    json: {
      // original supplier data
      ...original,

      // AI classification
      ...parsed,

      // timestamp
      processed_at: new Date().toISOString()
    }
  };
});

return items.map(item => {
  let raw = item.json.output;

  // remove ```json if present
  if (raw) {
    raw = raw.replace(/```json/g, "").replace(/```/g, "").trim();
  }

  let parsed = {};
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    return { json: {} };
  }

  const rec = parsed.recommendation || {};

  return {
    json: {
      // original supplier
      supplier_name: item.json.supplier_name,
      supplier_id: item.json.supplier_id,
      category: item.json.category,
      country: item.json.country,
      diversity_status: item.json.diversity_status,
      diversity_score: item.json.diversity_score,

      // recommendation
      recommendation_name: rec.supplier_name,
      diversity_type: rec.diversity_type,
      certification: rec.certification,
      region: rec.region,
      reason: rec.reason
    }
  };
});

